function checkPalindrome(str) {
    str = str.toLowerCase(); // Convert to lowercase for case-insensitive comparison
    let left = 0;
    let right = str.length - 1;

    while (left < right) {
        if (str[left] !== str[right]) {
            return false;
        }
        left++;
        right--;
    }

    return true;
}

A race condition is an issue that occurs when two or more threads access shared resources simultaneously and can cause inconsistencies in the outcome of their operations. This happens because each thread has its own copy of the data being accessed, but they may not be synchronized properly.

Here's a simple example:

